const tideSpiritSheet=new Image();tideSpiritSheet.assetSrc='assets/tide-spirit-v2.png';
function beginTideSpirit(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'tideAlternatingWaves',bespoke:true,windup:1.2,origin:{x:e.x,y:e.y},angle,hits:[false,false],sounds:[false,false]};}
const tideSpiritAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r8e7')return tideSpiritAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='tideAlternatingWaves'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=380&&clear){beginTideSpirit(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,64*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,20)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((before+dt)*1e6)/1e6;
 for(let i=0;i<2;i++){let start=1.2+i*1.2,end=start+.8;if(e.elapsed<start||before>end)continue;if(!a.sounds[i]){a.sounds[i]=true;playSound('impact',e.x,e.y);}let lo=Math.max(0,Math.min(420,(before-start)/.8*420)),hi=Math.max(0,Math.min(420,(e.elapsed-start)/.8*420)),dx=p.x-a.origin.x,dy=p.y-a.origin.y,along=dx*Math.cos(a.angle)+dy*Math.sin(a.angle),side=-dx*Math.sin(a.angle)+dy*Math.cos(a.angle),gap=i===0?-90:90;if(!a.hits[i]&&along>=lo-18-1e-8&&along<=hi+18+1e-8&&Math.abs(side)<=200+1e-8&&Math.abs(side-gap)>=55-1e-8&&lineClear(a.origin,p)){a.hits[i]=true;e.struck=true;hurt(72);}}
 if(e.elapsed>=3.8){e.attack=null;e.state='idle';e.t=3;}
};
const tideSpiritDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r8e7'||!tideSpiritSheet.complete||!tideSpiritSheet.naturalWidth||!tideSpiritSheet.naturalHeight)return tideSpiritDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='tideAlternatingWaves')f={row:2,col:e.elapsed<.6?0:e.elapsed<1.2?1:e.elapsed<3.2?2:3};let q=project(e.x,e.y),sw=tideSpiritSheet.naturalWidth/4,sh=tideSpiritSheet.naturalHeight/3,w=275,h=w*sh/sw,anchor=[.88,.89,.89][f.row];ctx.save();ctx.translate(q.x,q.y-(e.hp>0?Math.sin((e.anim||0)*2.5)*5:0));ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,tideSpiritSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(tideSpiritSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const tideSpiritSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r8e7'?175:tideSpiritSizeBase(e);
const tideSpiritGroundBase=drawGroundEffects;drawGroundEffects=()=>{tideSpiritGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r8e7'):enemies)){let a=e.attack;if(e.species!=='r8e7'||e.hp<=0||a?.pattern!=='tideAlternatingWaves'||e.elapsed>=3.2||!visibleAt(e.x,e.y,500))continue;let i=e.elapsed<2.1?0:1,start=1.2+i*1.2,gap=i===0?-90:90,q=project(a.origin.x,a.origin.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.rotate(a.angle);ctx.fillStyle='#72b7cf18';ctx.fillRect(0,-200,420,gap+145);ctx.fillRect(0,gap+55,420,145-gap);ctx.strokeStyle='#9ae4c3';ctx.lineWidth=1;ctx.strokeRect(0,gap-55,420,110);for(let j=0;j<2;j++){let t=e.elapsed-(1.2+j*1.2);if(t<0||t>.8)continue;let x=t/.8*420,g=j===0?-90:90;ctx.fillStyle='#8bd9ed88';ctx.fillRect(x-18,-200,36,g+145);ctx.fillRect(x-18,g+55,36,145-g);ctx.strokeStyle='#dafaff';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x,-200);ctx.lineTo(x,g-55);ctx.moveTo(x,g+55);ctx.lineTo(x,200);ctx.stroke();}ctx.restore();}};
